     5→// Heap state
     6→static mut HEAP_START: *mut u8 = core::ptr::null_mut();
     7→static mut HEAP_END: *mut u8 = core::ptr::null_mut();
     8→static mut HEAP_CURRENT: *mut u8 = core::ptr::null_mut();
     9→
    10→fn brk(addr: *mut u8) -> *mut u8 {
    11→    unsafe { syscall1(SYS_BRK, addr as u64) as *mut u8 }
    12→}
    13→
    14→pub fn init_heap() {
    15→    unsafe {
    16→        HEAP_START = brk(core::ptr::null_mut());
    17→        HEAP_END = HEAP_START;
    18→        HEAP_CURRENT = HEAP_START;
    19→    }
    20→}
    21→
    22→#[unsafe(no_mangle)]
    23→pub extern "C" fn malloc(size: usize) -> *mut u8 {
    24→    unsafe {
    25→        let aligned_size = (size + 15) & !15;
    26→        let new_current = HEAP_CURRENT.add(aligned_size);
    27→
    28→        if new_current > HEAP_END {
    29→            let grow_size = (aligned_size + 4095) & !4095;
    30→            let new_end = brk(HEAP_END.add(grow_size));
    31→            if new_end <= HEAP_END {
    32→                crate::io::write(2, b"malloc: brk failed\n".as_ptr(), 19);
    33→                return core::ptr::null_mut();
    34→            }
    35→            HEAP_END = new_end;
    36→        }
    37→
    38→        let ptr = HEAP_CURRENT;
    39→        HEAP_CURRENT = new_current;
    40→        ptr
    41→    }
    42→}
    43→
    44→/// Reallocate memory.
    45→///
    46→/// # Safety
    47→/// If `ptr` is non-null, it must have been returned by a previous call to
    48→/// `malloc`, `realloc`, or `calloc`, and `size` must not exceed the original
    49→/// allocation size (this simple allocator doesn't track sizes).
    50→#[unsafe(no_mangle)]
    51→pub unsafe extern "C" fn realloc(ptr: *mut u8, size: usize) -> *mut u8 {
    52→    if ptr.is_null() {
    53→        return malloc(size);
    54→    }
    55→    let new_ptr = malloc(size);
    56→    if !new_ptr.is_null() {
    57→        unsafe { memcpy(new_ptr, ptr, size) };
    58→    }
    59→    new_ptr
    60→}

